tool_input.command:
bash -c 'python3 - <<EOF
import re
p="app/Http/Controllers/ProfileController.ts"
s=open(p).read()
s=s.replace("import { pages } from \x27@/.guren/pages.gen\x27\n","import { pages } from \x27@/.guren/pages.gen\x27\nimport { apiTokenStore } from \x27../../Auth/ApiTokens.js\x27\n")
s=s.replace("""        email: user.email,
      },
    }, { title""","""        email: user.email,
      },
      tokens: await this.tokensFor(user.id),
    }, { title""")
s=s.replace("""      profile: { name, email },
      status""","""      profile: { name, email },
      tokens: await this.tokensFor(user.id),
      status""")
s=s.rstrip()[:-1]+"""
  // Names and dates only: the plain-text token is shown once, when created.
  private async tokensFor(userId: number) {
    const tokens = await apiTokenStore.findByUserId(userId)
    return tokens
      .toSorted((a, b) => b.createdAt.getTime() - a.createdAt.getTime())
      .map((token) => ({
        id: token.id,
        name: token.name,
        createdAt: token.createdAt.toISOString(),
        lastUsedAt: token.lastUsedAt?.toISOString() ?? null,
      }))
  }
}
"""
open(p,"w").write(s)
EOF'; git diff app/Http/Controllers/ProfileController.ts | head -50
